Cypher query: MATCH (a:Article)
WITH a, [toLower(coalesce(a.name, ''))] + [alias IN coalesce(a.aliases, []) | toLower(alias)] AS texts
WHERE (
  any(t IN texts WHERE t CONTAINS 'google' AND t CONTAINS 'canad' AND (t CONTAINS 'publisher' OR t CONTAINS 'media' OR t CONTAINS 'pay'))
  AND EXISTS {
    MATCH (a)-[:PUBLISHED_BY]->(pub)
    WHERE (pub:`Publisher OR pub`:Organization)
      AND (toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  }
) OR (
  any(t IN texts WHERE t CONTAINS 'google' AND (t CONTAINS 'lawsuit' OR t CONTAINS 'sues' OR t CONTAINS 'legal') AND (t CONTAINS 'publisher' OR t CONTAINS 'media'))
  AND EXISTS {
    MATCH (a)-[:PUBLISHED_BY]->(pub)
    WHERE (pub:`Publisher OR pub`:Organization)
      AND (toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  }
) OR (
  any(t IN texts WHERE t CONTAINS 'google' AND t CONTAINS 'pixel 8')
  AND EXISTS {
    MATCH (a)-[:PUBLISHED_BY]->(pub)
    WHERE (pub:`Publisher OR pub`:Organization)
      AND (toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  }
) OR (
  any(t IN texts WHERE t CONTAINS 'google search' AND t CONTAINS 'better' AND t CONTAINS 'fair')
  AND EXISTS {
    MATCH (a)-[:PUBLISHED_BY]->(pub)
    WHERE (pub:`Publisher OR pub`:Organization)
      AND (toLower(pub.name) CONTAINS 'the age' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the age'))
  }
)
OPTIONAL MATCH (a)-[:PUBLISHED_BY]->(pub)
OPTIONAL MATCH (a)-[r:MENTIONS|SAID|PARTICIPATED_IN|PART_OF]->(e)
RETURN a.name AS article, a.published_on AS published_on, pub.name AS publisher,
       type(r) AS relationship, e.name AS connected_entity, labels(e) AS entity_types
LIMIT 10
